alter table public.questions add column if not exists mode text not null default 'both';
alter table public.questions add column if not exists follow_up text;
alter table public.questions drop constraint if exists questions_mode_check;
alter table public.questions add constraint questions_mode_check check (mode in ('pair','group','both'));
alter table public.questions drop constraint if exists questions_question_type_check;
update public.questions set question_type = 'ab' where question_type = 'standard';
alter table public.questions alter column question_type set default 'ab';
alter table public.questions add constraint questions_question_type_check
  check (question_type in ('ab','ab_reason','open','guess','open_pick','impression'));

insert into public.topics (slug, label, sort_order, active) values
  ('social-moves','Social Moves',10,true),
  ('timing','Timing & Plans',11,true),
  ('friend-stuff','Friend Stuff',12,true),
  ('being-known','Being Known',13,true),
  ('honesty','Honesty',14,true),
  ('group-life','Group Life',15,true),
  ('you-lately','You Lately',16,true),
  ('looking-ahead','Looking Ahead',17,true)
on conflict (slug) do update set label = excluded.label, active = true;

update public.questions set active = false where question_type = 'impression';

