insert into public.questions (topic_id, text, option_a, option_b, spice_level, question_type, mode, active, follow_up)
select tm.id, b.text, b.option_a, b.option_b, b.spice_level, b.question_type, b.mode, b.active, b.follow_up
from bank b join topic_map tm on tm.slug = b.topic_slug;

